from review import card,save,DATE

i='TCS-3151';_,c=card(i);refs=c['references'];refs[0]['locator']='Sections 2.1–2.2, Definitions 1–4; Section 4, final paragraph (decomposability question).'
refs.append(dict(id='full2023',title='A general framework for enumerating equivalence classes of solutions — extended version',authors=refs[0]['authors'],year=2023,url='https://arxiv.org/abs/2004.12143',pdf_url='https://arxiv.org/pdf/2004.12143v4',locator='Version 4, 14 May 2023, Definitions 1–4 and Section 4, pp. 15–16; the question remains in the conclusion.'))
issue='Dropping decomposability can produce shared solution DAGs, while the source defines equivalence classes as colored rooted trees. The extension must specify whether solutions retain sharing and one choice per original OR vertex, or are unfolded into occurrence trees; what information class equality preserves; and the output encoding. Polynomial delay must then be measured against an explicit size convention. The concluding question does not fix these choices or a particular hardness assumption/reduction.'
save(i,dict(title='Enumerating equivalent solutions without AND/OR decomposability',formal='Does removing decomposability make enumeration of the source’s equivalence classes computationally hard? Keep the finite explicit acyclic bipartite AND/OR graph and its e-coloring, but allow different children of an AND vertex to reach common vertices. The intended comparison is with the paper’s polynomial-delay enumeration in the decomposable case. The source does not complete the definition of equivalence or output size for the resulting shared solution graphs, so a fully specified hardness or polynomial-delay proposition is still needed.',definitions='The input graph has AND vertices A and OR-plus vertices O, with arcs only between A and O and no directed cycles. Every AND vertex has positive indegree and outdegree. Sinks in O are goals; the other vertices in O are OR vertices, and OR vertices with indegree zero are starts. Decomposability requires the sets reachable from distinct children of any AND vertex, including those children, to be disjoint. An e-coloring assigns colors from a finite ordered alphabet to O so that the children of each AND vertex have different colors. In the decomposable model, a solution rooted at one start follows exactly one outgoing choice at each included OR vertex and all outgoing arcs at each included AND vertex, ending at goals. It is a tree. Contracting each chosen AND step connects its parent OR vertex directly to its OR-plus children. Two solutions are equivalent when these resulting rooted colored trees are isomorphic, preserving the root and colors but forgetting input-vertex identities. Enumeration outputs each resulting class once. Polynomial delay means a polynomial bound on the time before the first output, between consecutive outputs, and after the last output until termination, measured in input length; the explicit decomposable trees have size bounded by the input graph. Without decomposability, the analogous subgraph may share descendants and need not be a tree. Unfolding such a graph can enlarge its explicit representation substantially, so the choice of graph or tree output affects the proposed delay bound.',question_type='yes_no',answer_criterion='First fix the source-compatible shared-solution semantics, class equivalence, output encoding and delay measure. A resolution must then establish a polynomial-delay enumeration algorithm or a precisely stated hardness obstruction in that model. A result relying on decomposability, removing acyclicity as well, or merely counting labeled solutions does not resolve the intended extension.',context_blocks=[dict(title='Many derivations can describe the same outcome',text='An AND/OR representation can encode alternative derivations of a dynamic-programming solution. The paper groups derivations by their colored tree of outcomes, allowing enumeration to describe solution diversity without repeating equivalent derivations.',citation='primary'),dict(title='The missing restriction is decomposability',text='The paper proves polynomial-delay enumeration when the subproblems below each AND vertex have disjoint reachable state sets. The question asks about removing that independence condition; the imported summary had incorrectly suggested that an existing hardness result was being extended.',citation='primary'),dict(title='A later version preserves the question',text='The May 2023 extended version keeps the same concluding question. Its definitions explicitly observe that dropping decomposability can destroy the tree property, but do not redefine the colored-tree classes for that case.',citation='full2023'),dict(title='Remaining specification',text=issue)],why='Tests whether independence of subproblems is essential for efficiently enumerating distinct outcomes from a compact representation, rather than merely generating many redundant derivations.',references=refs,progress=[dict(date='2021',text='Polynomial-delay enumeration is established for e-colored acyclic decomposable AND/OR graphs; removing decomposability is posed as a further question.',citation='primary'),dict(date='2023-05-14',text='The extended version retains the question and the tree-based equivalence definitions.',citation='full2023')],status='source_open',status_note='Checked both published and May 2023 extended definitions and conclusions, and searched for subsequent work through 12 September 2026. No resolution was identified; the semantics of the requested extension remain incomplete.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered decomposability and the colored-tree quotient.']),importance=dict(score=c['importance']['score'],method='editorial',reason='Examines an independence boundary for duplicate-free enumeration from dynamic-programming representations. Existing score retained.',assessed_on=DATE),review_note='Corrected the direction of the question and explained the known tractable model. Retained the genuine ambiguity created by allowing shared descendants.',working_summary=dict(sentences=['The input is an acyclic AND/OR graph representing alternative decompositions of solutions.','Solutions are grouped by the colored rooted trees obtained after removing their AND steps.','The source can enumerate these classes with polynomial delay when subproblems below each AND vertex are disjoint.','It asks whether enumeration becomes hard after that decomposability condition is removed.','Shared descendants then require an explicit choice of solution semantics, class identity and output-size convention, which the conclusion does not supply.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full2023'])),notes=['Named the removed restriction and defined the original AND/OR model.','Corrected the imported summary’s reversed tractability/hardness premise.','Checked the 2023 full version and retained its unresolved extension semantics.'],checked_sources=[r['url'] for r in refs],state='improved_unfinished')

i='TCS-3152';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 2 (System F and atomic instantiation); concluding discussion, p. 27:15; reference 46.'
refs.extend([dict(id='overflow2018',title='Proof nets and the instantiation overflow property',authors='Paolo Pistone',year=2018,url='https://arxiv.org/abs/1803.09297',pdf_url='https://arxiv.org/pdf/1803.09297v1',locator='Definition 5.1, p. 24; Theorem 8 and Section 8, pp. 45–46. The theorem assumes a simple, quantifier-free body.'),dict(id='author',title='Paolo Pistone — publications',authors='Paolo Pistone',year=None,url='https://perso.ens-lyon.fr/paolo.pistone/',locator='Publication list checked 12 September 2026, including 2026 work and the instantiation-overflow preprint.'),dict(id='naturality2022',title='The Naturality of Natural Deduction (II): On Atomic Polymorphism and Generalized Propositional Connectives',authors='Paolo Pistone; Luca Tranchini; Mattia Petrolo',year=2022,url='https://doi.org/10.1007/s11225-021-09964-z',locator='Publisher abstract and references checked; published online 29 October 2021, volume 110 (2022), pp. 545–592. Abstract concerns connective encodings and parametricity; no general classification is claimed there. Full proof not inspected for this check.')])
issue='The property and the domain of types can be defined exactly, but the source requests a characterization without specifying an admissible form of structural criterion. It does not select a finite grammar, an effective decision procedure, or a fixed candidate class to prove equivalent. Its cited preprint lists decidability separately. Choosing one of those targets would change the requested classification; the answer format must be fixed before this is a fully specified benchmark.'
save(i,dict(title='Which polymorphic types have instantiation overflow?',formal='Characterize all types ∀X.A having the following property: for every System F type B, there is a term t_B with no free term variables such that ⊢ t_B : (∀X.A) → A[B/X] in atomic System F, denoted F_at. The body A may itself contain quantifiers, and substitution avoids capture. This is instantiation overflow. The intended classification must cover all such A, not just quantifier-free bodies. The source does not prescribe the form of the requested characterization, so the displayed membership property is exact but the final answer format remains to be specified.',definitions='Types are finite expressions generated from a countable supply of type variables by A ::= X | A→A | ∀X.A, modulo renaming bound variables. A[B/X] replaces the free occurrences of X in A by B, renaming bound variables to avoid capture. Free type variables are allowed. Church-style F_at terms are variables, typed lambda abstractions, applications, type abstractions ΛX.t, and type applications t[Y], where Y must be a type variable. In a finite context Γ assigning types to distinct term variables, the rules are: a declared variable has its assigned type; Γ,x:C ⊢ t:D yields Γ ⊢ λx:C.t:C→D; Γ ⊢ t:C→D and Γ ⊢ u:C yield Γ ⊢ tu:D; Γ ⊢ t:C yields Γ ⊢ ΛY.t:∀Y.C when Y is not free in any type of Γ; Γ ⊢ t:∀Y.C yields Γ ⊢ t[Z]:C[Z/Y] for a type variable Z. Context assumptions may be reused or left unused. Full System F instead allows any type as the last rule’s witness. Instantiation overflow requires the existence of an atomic-typed term for every B, with the term permitted to depend on A, X and B. It does not require the same term for all B, a resource bound on producing it, or equality to full instantiation under beta-eta conversion. A simple type is one with no quantifier anywhere in its body.',question_type='exact_value',answer_criterion='Give an exact classification of the defined set of types in a source-compatible characterization language, with both necessity and sufficiency proved. That characterization language remains unspecified, so this card is not certified as a finished exact-value task. Merely restating the universal typability definition, giving another sufficient family, or answering the distinct decidability question would not by itself supply the requested classification.',context_blocks=[dict(title='A restricted rule can sometimes recover its full instances',text='Atomic System F permits universal elimination only at a type variable. Instantiation overflow identifies quantified types whose arbitrary substitutions can nevertheless be realized by terms using that restricted rule. The issue concerns polymorphism in type theory, not operations preserving constraint relations.',citation='primary'),dict(title='The known classification has a restricted body',text='The cited 2018 preprint gives a necessary-and-sufficient characterization when A is a simple type, using derivability and logical equivalence to products of generalized Russell–Prawitz types. Its Theorem 8 does not classify arbitrary quantified bodies.',citation='overflow2018'),dict(title='Classification and decidability are different questions',text='The preprint separately asks about extending the classification to all System F types and about deciding instantiation overflow. The 2021 source points to the former classification gap. A decision problem is therefore not silently substituted for the original request.',citation='overflow2018'),dict(title='Remaining specification',text=issue)],why='Would identify exactly when a predicative restriction on universal elimination retains the effect of arbitrary type instantiation, clarifying the boundary between atomic and full polymorphism.',references=refs,progress=[dict(date='2018-03-25',text='A preprint supplies a full characterization for quantifier-free bodies, and leaves the arbitrary-System-F extension open.',citation='overflow2018'),dict(date='2021',text='The FSCD paper identifies the general classification of instantiation-overflow types as an open problem.',citation='primary')],status='source_open',status_note='Read the atomic typing rules, the original question, and the cited preprint’s exact property and restricted characterization. Checked the author’s publication list and later publisher records through 12 September 2026; no general classification was identified. The answer format is still unspecified.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered instantiation overflow and distinguished simple bodies from arbitrary polymorphic types.']),importance=dict(score=c['importance']['score'],method='editorial',reason='Concerns the structural boundary of the expressive power of restricted universal elimination. Existing score retained.',assessed_on=DATE),review_note='Replaced the missing-property excerpt with the exact typability condition and complete atomic rules. Preserved the general classification request without inventing an algorithmic target.',working_summary=dict(sentences=['Atomic System F allows a universally quantified type to be instantiated directly only at another type variable.','A type has instantiation overflow if atomic-typed terms can still realize every arbitrary substitution into its quantified body.','The question asks for a classification of all such types, including bodies with nested quantifiers.','The cited characterization covers only quantifier-free bodies, and decidability is a separately stated question.','The property is now explicit, but the source still leaves the required form of a general characterization unspecified.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','overflow2018','author','naturality2022'])),notes=['Defined the missing instantiation-overflow property and F_at typing rules.','Checked Definition 5.1 and Theorem 8 of the cited preprint.','Separated general classification, simple-body results and the distinct decidability question.','Recorded the remaining characterization-format choice instead of inventing a yes/no conjecture.'],checked_sources=[r['url'] for r in refs],state='improved_unfinished')

i='TCS-3153';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 4, Open Problems, p. 10:15; Appendix A.1–A.2 for Fourier sparsity and rank.'
refs.extend([dict(id='sanyal2019',title='Fourier Sparsity and Dimension',authors='Swagato Sanyal',year=2019,url='https://theoryofcomputing.org/articles/v015a011/',pdf_url='https://theoryofcomputing.org/articles/v015a011/v015a011.pdf',locator='Theory of Computing 15(11), Theorem 1.2 and the addressing example immediately preceding it, pp. 2–3.'),dict(id='testing2026',title='Spectral Norm, Economical Sieve, and Linear Invariance Testing of Boolean Functions',authors='Swarnalipa Datta; Arijit Ghosh; Chandrima Kayal; Manaswi Paraashar; Manmatha Roy',year=2026,url='https://doi.org/10.4230/LIPIcs.STACS.2026.30',pdf_url='https://drops.dagstuhl.de/storage/00lipics/lipics-vol364-stacs2026/LIPIcs.STACS.2026.30/LIPIcs.STACS.2026.30.pdf',locator='Section 2.2 and reference 34; also checked arXiv:2308.02662v2, revised 13 January 2026. The background citation omits the logarithmic factor present in the cited 2019 theorem.')])
save(i,dict(title='Can Boolean Fourier rank grow faster than the square root of sparsity?',formal='Does there exist a sequence of integers n_j≥1 and Boolean functions f_j:{−1,1}^{n_j}→{−1,1} such that k(f_j)→∞ and r(f_j)/√k(f_j)→∞ as j→∞, where k is Fourier sparsity and r is Fourier rank over F₂? Equivalently, is the ratio r(f)/√k(f) unbounded over all finite-dimensional Boolean functions?',definitions='For n≥1 and S⊆[n], put χ_S(x)=∏_{i∈S}x_i, with χ_∅=1. The Fourier coefficient is f̂(S)=2^{−n}∑_{x∈{−1,1}^n}f(x)χ_S(x), so f=∑_{S⊆[n]}f̂(S)χ_S. The support is supp(f̂)={S:f̂(S)≠0}, and k(f)=|supp(f̂)|. It is at least one. Identify a subset S with its incidence vector in F₂^n and define r(f)=dim_{F₂} span{1_S:S∈supp(f̂)}. The empty set contributes the zero vector; it may count towards k but never increases r. This rank is not a real linear-span dimension of functions. The limit r(f_j)=ω(√k(f_j)) means that for every real M>0, the ratio eventually exceeds M. No bound on n_j in terms of j, explicit construction algorithm, or computational efficiency is requested. The negation is the existence of a universal constant C such that r(f)≤C√k(f) for every n and every such f. Since r(f)≤k(f), unbounded ratios necessarily require unbounded sparsities.',question_type='yes_no',answer_criterion='A positive answer must prove the existence of functions with unbounded r(f)/√k(f), equivalently a sequence with the displayed limits. A negative answer must prove a universal constant-factor square-root bound for every Boolean function. A fixed larger constant, finitely many examples, or a bound retaining a growing logarithmic factor does not decide the question.',context_blocks=[dict(title='Support size and independent parity directions',text='Fourier sparsity counts the nonzero parity coefficients. Rank counts how many independent parity directions are needed to contain their support. The question asks how far these two structural measures can diverge at the square-root scale.',citation='primary'),dict(title='The known gap is logarithmic',text='Sanyal’s published Theorem 1.2 gives r(f)=O(√k(f) log(k(f)+1)). Addressing functions attain the square-root scale up to constants. The 2021 paper explicitly asks whether that scale can be exceeded by an unbounded factor.',citation='sanyal2019'),dict(title='A later citation does not remove the factor',text='The 2026 linear-invariance-testing paper describes a square-root bound up to constants in a background sentence and cites Sanyal’s 2019 result. Checking that cited theorem shows that it includes log k. This citation therefore does not establish the stronger universal bound that would negatively resolve the present question.',citation='testing2026')],why='Would determine whether sparse Boolean Fourier support necessarily occupies only square-root-many independent parity directions, or whether the familiar quadratic relation misses a growing separation.',references=refs,progress=[dict(date='2019',text='The published upper bound is O(√k log k), within a logarithmic factor of addressing examples.',citation='sanyal2019'),dict(date='2021',text='The source explicitly asks whether r=ω(√k) occurs for any family of Boolean functions.',citation='primary'),dict(date='2026',text='A later property-testing paper cites the 2019 dimension bound in its background; checking the cited theorem preserves the logarithmic gap.',citation='testing2026')],status='source_open',status_note='Checked the 2021 question, the exact published 2019 theorem, and the 2026 property-testing paper and its cited bound. Searches through 12 September 2026 found no resolution of the unbounded-ratio question. The 2026 background wording is not treated as a new rank theorem.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='Asks for the exact qualitative relation between two fundamental Boolean Fourier complexity measures. Existing score retained.',assessed_on=DATE),review_note='Restored the lost square root, defined rank over F₂, and replaced a statement about one function by the required asymptotic family. Verified the logarithmic factor against the primary theorem.',working_summary=dict(sentences=['A Boolean function has a Fourier expansion in parity characters.','Its sparsity counts nonzero coefficients, while its rank is the F₂ dimension spanned by their index sets.','The question asks whether rank can exceed the square root of sparsity by an unbounded factor.','Known addressing examples attain the square-root scale, and the published universal upper bound allows an additional logarithmic factor.','The answer requires either an asymptotically separating family or a universal square-root bound with an absolute constant.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','sanyal2019','testing2026'])),notes=['Restored the square-root expression and the asymptotic family quantifiers.','Defined Fourier normalization, support and F₂ rank, including constant functions.','Stated both the unbounded-ratio target and its exact universal-bound negation.','Checked the later 2026 citation against the 2019 theorem rather than accepting its dropped logarithm.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2308.02662'])
